import{C as a,c as u}from"./dom-6kYVTdCz.js";import{b as x,c as n,t}from"./header-Bo-VLoH0.js";const F={"ni.character.awareness.why":"certain of the shape, unable to show its work","ni.character.control.why":"insights arrive on their own schedule; the tiller answers slowly","ni.character.endurance.why":"convergence is patient — the funnel runs for hours without strain","ni.character.precision.why":"one trajectory, fitted tight; the envelope narrows as it runs","ni.character.speed.why":"convergence waits for the fit — insight arrives whole, and late","ni.energy.recovery.auxiliary":"Clean recovery once the read has been handed over to somebody.","ni.energy.recovery.dominant":"Refills partly during use — every insight that lands pays a little back.","ni.energy.recovery.inferior":"The hangover shelf: ~30 min where the whole system runs dim and the doom-read keeps repeating.","ni.energy.recovery.shadow":"Incomplete — some of the charge simply does not come back today.","ni.energy.recovery.tertiary":"Slower: the pattern-chasing has to actually be put down first.","ni.feeder.fe":{figure:"Many soft channels feeding one patient line.",mechanism:"Fe — extraverted feeling — returns the state of the room: what is going on between these particular people and what they are likely to do with it. More channels, smaller inputs, an image about trajectories of relationship. Correction arrives socially — slower than a number, and harder to dismiss.",pair:"the INFJ · ENFJ coupling",provenance:"myers"},"ni.feeder.fi":{figure:"The line darkens without moving.",mechanism:"The INTJ loop, with Te cut out: Fi — introverted feeling — supplies judgment, also from inside, weighing the image against what matters to one person and nothing else. Airless and self-confirming: a read of how all this goes that grows more certain the longer nobody outside touches it, and no more accurate.",pair:"the INTJ Ni–Fi loop",provenance:"community",warn:"Loop coupling: introverted judging feeding introverted perception — no correction from outside."},"ni.feeder.se":{figure:"Fragments arrive faster than they can be held; the picture keeps almost forming and leaking away.",mechanism:"Se — extraverted sensing — floods the intake with the present: dense, concrete, immediate, all of it true and none of it going anywhere, while nothing sorts any of it — both functions gather and neither judges. These two also sit on the same axis: what one takes as obvious, the other treats as noise. Real stacks alternate perceiving and judging for exactly this reason.",pair:"perception feeding perception",provenance:"myers",warn:"Unstable coupling: perception feeding perception, with nothing judging either."},"ni.feeder.te":{figure:"A thin, aimed stream; the envelope tightens where the numbers land.",mechanism:"Te — extraverted thinking — hands back results, measurements, and the state of the plan: few inputs, each hard, each on a narrow aimed channel. The image that forms is about how a structure moves over years, and it gets corrected when the numbers disagree. The bluntest error-correction Ni has, and the most reliable.",pair:"the INTJ · ENTJ coupling",provenance:"myers"},"ni.feeder.ti":{figure:"The boundary seals one turn further; notice how often the fit fires early in this state.",mechanism:"The INFJ loop, with Fe cut out: Ti — introverted thinking — supplies judgment, but from inside. The image is checked for internal consistency and never against anything in the room, so convergence gets faster and certainty tighter — and the only thing correcting the picture is the same head that produced it.",pair:"the INFJ Ni–Ti loop",provenance:"community",warn:"Loop coupling: introverted judging feeding introverted perception — no correction from outside."},"ni.fieldNotes.mirror":{figure:"Two funnels, mouth to mouth.",mechanismHtml:"Same element, opposite attitude — and the difference is which way the funnel points. <strong>Ne</strong> takes one input and fans it into many futures, all live at once, all cheap to hold, none of them chosen. <strong>Ni</strong> takes many inputs and funnels them into one, and that one arrives whole, expensive to change, and impossible to show. Ne trades commitment for range; Ni trades range for a conviction it cannot source.",provenance:"jung"},"ni.fieldNotes.vignette.brainstorm":{figure:"A funnel cannot be run as a sprinkler.",kind:"the wrong instrument",mechanism:"Ask Ni for twenty quick options and watch the instrument refuse the spec: it will sit silent through the sticky-note flurry and eventually offer one option, late, fully formed, with the argument for it welded on. The convergence that makes it valuable is exactly what makes it wrong here. Teams that know this stop grading Ni on volume and start handing it the shortlist instead.",provenance:"community",title:"The Brainstorm"},"ni.fieldNotes.vignette.cantJustKnow":{figure:"An instrument that cannot print its raw data.",kind:"the accusation",mechanism:"The accusation treats a missing derivation as a missing basis. What is actually missing is an interface: the funnel consumed hundreds of observations and returned only the destination, and the intermediate steps were never stored anywhere retrievable. The correct response to an Ni read is neither faith nor dismissal — it is treating it as a measurement from an instrument that cannot show its work, and testing it like any other measurement.",provenance:"currents",title:`"You Can't Just Know That"`},"ni.fieldNotes.vignette.grip":{figure:"The horizon snaps to arm's length.",kind:"the grip",mechanism:"An INTJ past the end of their reserves stops seeing where anything is going and floods into inferior Se — buying things, driving too fast, eating and drinking past the point of noticing, working the body until it is the only thing in the room. Not a personality change: a low-capacity seat taking a dominant-sized flood.",provenance:"quenk",title:"The Grip"},"ni.fieldNotes.vignette.loop":{figure:"Sealed, elaborate, certain.",kind:"the loop",mechanism:"Under stress, an INFJ's dominant Ni pairs with tertiary Ti — both facing inward, with Fe's contact with actual people cut out between them. The read gets more elaborate, more internally consistent, and more certain, and nobody outside that head has touched it in weeks. This same-direction pattern is called a loop.",provenance:"community",title:"The Loop"},"ni.fieldNotes.vignette.mechanicsHunch":{figure:"Narrow-band foresight, calloused hands.",kind:"as a tertiary",mechanism:'Tertiary Ni in an ISTP or ISFP: a quiet convergence engine under a hands-on exterior. It surfaces as the mechanic who stops mid-job because the fault is "not going to be the alternator," the climber who reroutes for a reason that arrives as certainty before it arrives as weather. Narrow-band, body-adjacent foresight — trusted about machines and terrain, and rarely invited to opine about anything else.',provenance:"grant",title:"The Mechanic's Hunch"},"ni.fieldNotes.vignette.meeting":{figure:"The funnel returned only the destination.",kind:"field sighting",mechanism:"Ten minutes in, an Ni-dominant knows how the project ends, and says so. Asked why, they produce a reason that is true but is not the reason — it is the nearest sayable thing to a read that never had steps. Six months later they turn out to be right, which does nothing at all to improve the next explanation.",provenance:"community",title:"The Meeting"},"ni.fieldNotes.vignette.mistakenForSi":{figure:"The record versus the vector.",kind:"the misread",mechanism:'Both are quiet, careful, and interior, so the two introverted perceivers get collapsed — usually as "detail people." The tell is what "how do you know?" retrieves. Si produces the record: the date, the precedent, the last three times this exact thing happened. Ni produces the shape: where this is heading, stripped of every particular that built the trajectory. One archives the past at full resolution; the other compresses it beyond recovery.',provenance:"community",title:"Mistaken for Si"},"ni.hero.heading":"The Convergence of {fn}","ni.hero.subtitle":"A field of scattered observations, one trajectory fitted through them — and a single construct riding the line through time, already sure of where it bends.","ni.hero.tag":"introverted intuition","ni.lab.btn.aha.label":"Aha! Synthesis","ni.lab.btn.aha.sub":"inject disparate data → synthesize paradigm","ni.lab.btn.cassandra.label":"Cassandra Tragedy","ni.lab.btn.cassandra.sub":"forecast ignored → predicted failure occurs","ni.lab.btn.flash.label":"Flash Tactical Interruption","ni.lab.btn.flash.sub":'"make the call now!"',"ni.lab.btn.focus.label":"Deep Focus Simulation","ni.lab.btn.focus.sub":"enter a deep uninterrupted focus block","ni.lab.btn.overfit.label":"Micromanagement Overfit","ni.lab.btn.overfit.sub":"force granular spreadsheet formatting","ni.lab.meter.pleasure":"Pleasure","ni.lab.meter.stress":"Stress","ni.lab.narration.aha":{figure:"The residuals collapse and the variance envelope pulls tight.",mechanism:"Two dozen observations with no business belonging together — and for a moment they don't. Then one trajectory claims every outlier at once, and what was a cloud is suddenly a line with a direction. Note the order of events: the answer arrived, and then it was obvious.",provenance:"currents"},"ni.lab.narration.aha2":{figure:"R² near unity, loss near zero, stress gone.",mechanism:"This is the payment Ni works for — not praise, not results: compression. Twenty things became one thing, and the one thing predicts. The outliers that produced it are already indistinguishable from the line they joined.",provenance:"currents"},"ni.lab.narration.cassandra":{figure:"Watch the construct arrive at the crossing it named in advance.",mechanism:"The model saw this. The read has pointed through the failure boundary for some time, and saying so out loud changed nothing.",provenance:"currents"},"ni.lab.narration.cassandra2":{figure:"The confidence readout never moved.",mechanism:"Failure, on schedule. The fit was precise the entire time — which is the specific cruelty here: being right early is indistinguishable, from outside, from being wrong right up until it stops being. The small bitter lift on the pleasure meter is real, and it is not a nice feeling.",provenance:"currents"},"ni.lab.narration.flash":{figure:"The trajectory shatters into high-frequency noise as the present tense barrages the viewport.",mechanism:'"Make the call now." The one resource this function runs on — time to simulate — is the one just revoked. It does not have a fast answer; it has a buffering answer, and the buffer has been ordered to stall.',provenance:"currents"},"ni.lab.narration.flash2":{figure:"The line reassembles from a lower fit.",mechanism:"The barrage passes and the re-fit begins from a knocked-down R². Nothing was learned during the interruption; time under fire is not data, just time. What a deadline buys from Ni is not speed — it is whichever guess was lying around when the clock hit zero.",provenance:"currents"},"ni.lab.narration.focus":{figure:"The trajectory extends smoothly past the viewport's edge.",mechanism:"The door closes and the input stops arriving — not solved, just no longer incoming. Projection extends: one step past now, then another, with the uncertainty barely widening. This is the machine doing what it is priced for, at the depth it is priced for.",provenance:"currents"},"ni.lab.narration.focus2":{figure:"Same points, longer line.",mechanism:"Note what deep focus did not do: it added no data. Foresight got longer on the same observations, because uninterrupted simulation is how this function converts held material into reach. The cheapest upgrade Ni ever gets is a closed door.",provenance:"currents"},"ni.lab.narration.hover":"You have the tiller. Left is earlier, right is later — and the construct's makeup at each point is what the model believes the concept looks like there. Notice it is the same object the whole way across: development, not replacement.","ni.lab.narration.intro":"The engine runs unattended: observations gather, a trajectory fits itself through them, and the construct rides the line from one end of time to the other, changing as it goes.","ni.lab.narration.introHintCoarse":"Press and drag left–right in the chamber to take the tiller yourself — or perturb the engine below and watch the telemetry respond.","ni.lab.narration.introHintFine":"Hover the chamber to take the tiller yourself — or perturb the engine below and watch the telemetry respond.","ni.lab.narration.overfit":{figure:"The trendline passes through each noise point individually; the horizon readout reads zero steps forward.",mechanism:"Every cell formatted, every local wiggle honoured. Accuracy on what already happened is spectacular — and the extrapolation is garbage: the model has memorised the residuals and forgotten the direction.",provenance:"currents"},"ni.lab.narration.overfit2":{figure:"The construct jitters to honour decimals.",mechanism:"This is what micromanagement costs a long-range instrument: generality. Forced to account for every cell, it can no longer say where anything is going — precision about the present, purchased with the future.",provenance:"currents"},"ni.lab.state.cynical":"Cynical Resignation","ni.lab.state.equilibrium":"Optimal Equilibrium","ni.lab.state.euphoric":"Euphoric Flow","ni.lab.state.freeze":"Overwhelm / Freeze","ni.lab.state.overfit":"Overfitted Fatigue","ni.lab.telemetry.cogState":"Cognitive state","ni.lab.telemetry.conf":"Predictive confidence","ni.lab.telemetry.loss":"Model loss","ni.meta.title":"Ni — Introverted Intuition · CURRENTS","ni.slot.auxiliary":{example:"An ENTJ's five-year plan contains one sentence of pure foresight; the rest is execution.",figure:"A four-fifths funnel, feeding a machine that ships.",mechanism:"In the second seat, the long read serves something already underway: it supplies direction rather than identity, and the dominant judging function converts it into a plan or a managed room. Quicker to state, easier to argue with, and far less likely to sit on one image for a decade.",provenance:"myers"},"ni.slot.critical":{example:"An INFP concludes at midnight that the pattern of their whole life is now visible, and it is not good.",figure:"One grey line through the self, extended to the horizon.",mechanism:"In the sixth seat, foresight turns inward and issues verdicts about one's own life — this is what you are, this is where it ends — total, unsourced, and aimed at nobody else. It forecasts far more confidently than it checks.",provenance:"beebe"},"ni.slot.demon":{example:"An ISFJ knows, for one terrible evening, exactly how everyone they love will leave.",figure:"A single line, drawn dark, through every point at once.",mechanism:"The eighth seat runs rarest and worst. When it erupts, it produces one black certainty about how all of this ends — applied to everything at once, immune to evidence, and unbothered that yesterday's version said something different. It is the least practised seat in the stack, not a prophecy.",provenance:"beebe"},"ni.slot.dominant":{example:"Ten minutes into the kickoff, an INFJ knows how the project ends — and takes six months to be provably right.",figure:"CURRENTS draws this as a regression at full depth: a tight envelope, an unhurried fit.",mechanism:"In the first seat, everything is read for where it is going, and the reading runs continuously, invisibly, at low cost. Long stretches pass in which nothing legible happens; then an answer arrives whole, already certain. Showing the steps is genuinely hard — the steps were never held separately.",provenance:"myers"},"ni.slot.inferior":{example:"An ESTP who never looks past tonight wakes at 4 a.m. sure the business is doomed, in detail.",figure:"A dim funnel that fires rarely, and always at the same dark point.",mechanism:"In the fourth seat, the future arrives as a verdict rather than a forecast. Long stretches of living in the present are punctuated — under fatigue or stress — by sudden total certainty that this ends badly, always was going to, and is not open to discussion, in a register that does not sound like them. This is Quenk's grip.",provenance:"quenk"},"ni.slot.opposing":{example:"Told the market only goes one way, an ENFP instantly narrates the crash — then orders dessert.",figure:"Below the waterline, a counter-trajectory drawn in one stroke and abandoned.",mechanism:"The fifth seat opens the shadow — the four positions a person runs rarely, and mostly without noticing. Here the long read wakes combative: when somebody else's single vision of the future starts closing options down, a rival certainty appears — darker, more inevitable, and held exactly long enough to refuse the first one.",provenance:"beebe"},"ni.slot.tertiary":{example:`The mechanic stops mid-job: "it's not going to be the alternator." It isn't.`,figure:"A half-size funnel that snaps into focus, then wanders.",mechanism:"In the third seat, pattern-reading arrives in bursts and is trusted unevenly: a sudden clear sense of how a situation plays out — usually sound, occasionally a whole story built on nothing — with little interest in defending either. It steadies with age, mostly by learning which of its own hunches to check.",provenance:"grant"},"ni.slot.trickster":{example:"An ESTJ misses the resignation letter between the lines, then finds a conspiracy in the seating plan.",figure:"The envelope never narrows; the fit lands beside the points.",mechanism:"In the seventh seat, implication is a rigged game: either nothing is between the lines or everything is. The seat alternates between missing subtext that was plainly there and constructing an elaborate one nobody meant — without malice, and usually without noticing which it just did.",provenance:"beebe"},"ni.zoneA.canvasAria":"Interactive visual representation of Introverted Intuition as a regression engine: scattered observations converge into one fitted trajectory with a confidence envelope, and a synthesized construct rides the line through time, morphing as it goes. Point at or drag across the chamber to steer the construct along the time axis","ni.zoneB.heading":"The Eight Faces of Ni","ni.zoneB.lede":"The canvas draws Ni as a regression: many observations in, one fitted trajectory out. Where Ni sits in a person's stack — the fixed order their eight functions come in — changes how the read behaves. Click a position to see the change, from the dominant's unhurried funnel to the demon's single black certainty, and watch the convergence readout: it tells the story before the caption does. Drag the maturity slider to watch the lower seats gain fidelity with age.","ni.zoneB.railAria":"Stack positions for Ni","ni.zoneC.heading":"What Feeds Into Ni?","ni.zoneC.lede":"Ni gathers; it does not judge. Introverted perception is fed by extraverted judgment, so its real partners are the outer judges — Te and Fe, the functions that bring correction in from outside. Click a feeder to watch what converges.","ni.zoneC.unstableDefault":"Unstable coupling: perception feeding perception, with nothing judging either.","ni.zoneD.canvasAria":"The Ni regression engine: scattered observations, a fitted trajectory with a variance envelope, and a construct that can be steered back and forth along the time axis by pointing or dragging","ni.zoneD.heading":"The Regression Engine","ni.zoneD.kicker":"Zone D · the regression engine","ni.zoneD.lede":"Ni fits one predictive trajectory through noisy, many-dimensional input, then rides it forward in time. This lab exposes the engine's live state — stress, pleasure, confidence, loss — and five ways a day can treat it. Trigger a scenario and watch the telemetry answer.","ni.zoneD.ledeHintCoarse":"Press and drag left–right in the chamber at any time to steer the construct through time yourself.","ni.zoneD.ledeHintFine":"Hover the chamber at any time to steer the construct through time yourself.","ni.zoneE.lede":"Patterns from the wild — how Ni shows up in daily life."};x(F);function j(){const i={fn:a("--c-accent"),n:a("--c-n"),s:a("--c-s"),f:a("--c-f"),pos:[a("--pos-1"),a("--pos-2"),a("--pos-3"),a("--pos-4")],sh:a("--pos-sh"),warn:a("--warn"),crit:a("--crit"),ink:a("--ink"),ink2:a("--ink-2"),muted:a("--muted"),grid:a("--grid"),axis:a("--axis"),surface:a("--surface")},o=e=>({name:t(`site.position.${e}.name`),ord:t(`site.position.${e}.ord`)}),p=[{key:"dominant",...o("dominant"),types:"INTJ · INFJ",shadow:!1,series:0,params:{scale:1,fidelity:.95,latency:0,noise:0,duty:1,control:1,contrary:0},copy:n("ni.slot.dominant")},{key:"auxiliary",...o("auxiliary"),types:"ENTJ · ENFJ",shadow:!1,series:1,params:{scale:.8,fidelity:.85,latency:80,noise:.05,duty:.85,control:.9,contrary:0},copy:n("ni.slot.auxiliary")},{key:"tertiary",...o("tertiary"),types:"ISTP · ISFP",shadow:!1,series:2,params:{scale:.55,fidelity:.6,latency:250,noise:.2,duty:.5,control:.6,contrary:0},copy:n("ni.slot.tertiary")},{key:"inferior",...o("inferior"),types:"ESTP · ESFP",shadow:!1,series:3,params:{scale:.4,fidelity:.35,latency:700,noise:.45,duty:.25,control:.35,contrary:.12},copy:n("ni.slot.inferior")},{key:"opposing",...o("opposing"),types:"ENTP · ENFP",shadow:!0,series:4,params:{scale:.46,fidelity:.42,latency:600,noise:.5,duty:.45,control:.4,contrary:.25},copy:n("ni.slot.opposing")},{key:"critical",...o("critical"),types:"INTP · INFP",shadow:!0,series:4,params:{scale:.44,fidelity:.35,latency:900,noise:.55,duty:.35,control:.3,contrary:.35},copy:n("ni.slot.critical")},{key:"trickster",...o("trickster"),types:"ESTJ · ESFJ",shadow:!0,series:4,params:{scale:.42,fidelity:.28,latency:1200,noise:.6,duty:.3,control:.2,contrary:.55},copy:n("ni.slot.trickster")},{key:"demon",...o("demon"),types:"ISTJ · ISFJ",shadow:!0,series:4,params:{scale:.4,fidelity:.2,latency:1500,noise:.65,duty:.22,control:.12,contrary:.65},copy:n("ni.slot.demon")}],g={endurance:{w:.95,why:t("ni.character.endurance.why")},precision:{w:.9,why:t("ni.character.precision.why")},speed:{w:.4,why:t("ni.character.speed.why")},control:{w:.6,why:t("ni.character.control.why")},awareness:{w:.85,why:t("ni.character.awareness.why")}},f=[{key:"te",name:"Te",color:"#17d4ef",canonical:!0,cfg:{rate:.1,weight:1.05,speed:.4,spread:.34,persistence:.95,aim:3.14},copy:n("ni.feeder.te")},{key:"fe",name:"Fe",color:"#f9748f",canonical:!0,cfg:{rate:.3,weight:.52,speed:.46,spread:.62,persistence:.9,aim:3.05},copy:n("ni.feeder.fe")},{key:"se",name:"Se",color:i.s,canonical:!1,unstable:!0,cfg:{rate:.95,weight:.16,speed:.95,spread:1,persistence:.18,starve:!0},copy:n("ni.feeder.se")},{key:"ti",name:"Ti",color:"#4fc9e0",canonical:!1,cfg:{rate:.26,weight:.85,speed:.55,spread:.45,persistence:.99,sealed:!0,aim:3.3},copy:n("ni.feeder.ti")},{key:"fi",name:"Fi",color:"#f56a8c",canonical:!1,cfg:{rate:.22,weight:.95,speed:.5,spread:.4,persistence:.99,sealed:!0,aim:2.95},copy:n("ni.feeder.fi")}];function m(e){const l=11.8*(e/60),h=e%18/18,c=2.6*Math.max(0,1-Math.abs(h-.06)*6);return Math.max(0,l-c)}function y(e){const l=19*Math.pow(e/60,1.22);let h=0;for(const[d,N]of[[13,11],[37,9],[64,13],[92,8]])e>=d&&(h+=N*u((e-d)/1.6,0,1));const c=e<2?0:1.7*Math.sin(e*.8)+1.3*Math.sin(e*2.1+.7);return u(l+h+c,0,100)}const s=[{key:"dom",label:t("site.position.dominant.name"),color:i.pos[0],f:m},{key:"aux",label:t("site.position.auxiliary.name"),color:i.pos[1],f:e=>20*Math.pow(e/60,1.06)},{key:"tert",label:t("site.position.tertiary.name"),color:i.pos[2],f:e=>29*Math.pow(e/60,1.4)},{key:"inf",label:t("site.position.inferior.name"),color:i.pos[3],f:e=>Math.min(100,84*Math.pow(e/60,1.9))},{key:"sh",label:t("site.position.shadow.name"),color:i.sh,f:y}],w=60*Math.pow(100/84,1/1.9),b=[{label:t("site.position.dominant.name"),v:1,color:i.pos[0],series:0},{label:t("site.position.auxiliary.name"),v:1.5,color:i.pos[1],series:1},{label:t("site.position.tertiary.name"),v:2.5,color:i.pos[2],series:2},{label:t("site.position.inferior.name"),v:4,color:i.pos[3],series:3},{label:t("site.position.shadow.name"),v:4.5,color:i.sh,band:[3,6],series:4}],v=[{label:t("site.position.dominant.name"),color:i.pos[0],note:t("ni.energy.recovery.dominant"),f:e=>e<=30?100-s[0].f(e):r(0)+(100-r(0))*(1-Math.exp(-(e-30)/7))},{label:t("site.position.auxiliary.name"),color:i.pos[1],note:t("ni.energy.recovery.auxiliary"),f:e=>e<=30?100-s[1].f(e):r(1)+(100-r(1))*(1-Math.exp(-(e-30)/11))},{label:t("site.position.tertiary.name"),color:i.pos[2],note:t("ni.energy.recovery.tertiary"),f:e=>e<=30?100-s[2].f(e):r(2)+(100-r(2))*(1-Math.exp(-(e-30)/17))},{label:t("site.position.inferior.name"),color:i.pos[3],note:t("ni.energy.recovery.inferior"),f:e=>e<=30?100-s[3].f(e):e<60?r(3):r(3)+(100-r(3))*(1-Math.exp(-(e-60)/21))},{label:t("site.position.shadow.name"),color:i.sh,note:t("ni.energy.recovery.shadow"),f:e=>e<=30?100-s[4].f(e):r(4)+(92-r(4))*(1-Math.exp(-(e-30)/26))}];function r(e){return 100-s[e].f(30)}const k={buttons:[{id:"btnAha",key:"aha",color:i.fn,impact:{stress:-.5,pleasure:.9},followMs:5600},{id:"btnCassandra",key:"cassandra",color:i.crit,impact:{stress:.85,pleasure:.3},followMs:7e3},{id:"btnFlash",key:"flash",color:i.warn,impact:{stress:.95,pleasure:-.8},followMs:6200},{id:"btnFocus",key:"focus",color:"#4fc9e0",impact:{stress:-.8,pleasure:.75},followMs:6200},{id:"btnOverfit",key:"overfit",color:i.s,impact:{stress:.65,pleasure:-.7},followMs:6200}],states:{euphoric:{label:t("ni.lab.state.euphoric"),color:"#17c964"},equilibrium:{label:t("ni.lab.state.equilibrium"),color:i.fn},cynical:{label:t("ni.lab.state.cynical"),color:i.warn},freeze:{label:t("ni.lab.state.freeze"),color:i.crit},overfit:{label:t("ni.lab.state.overfit"),color:i.sh}},narrations:{aha:n("ni.lab.narration.aha"),aha2:n("ni.lab.narration.aha2"),cassandra:n("ni.lab.narration.cassandra"),cassandra2:n("ni.lab.narration.cassandra2"),flash:n("ni.lab.narration.flash"),flash2:n("ni.lab.narration.flash2"),focus:n("ni.lab.narration.focus"),focus2:n("ni.lab.narration.focus2"),overfit:n("ni.lab.narration.overfit"),overfit2:n("ni.lab.narration.overfit2"),hover:t("ni.lab.narration.hover")}},T={mirror:{label:"Ni",counterpart:"Ne",counterpartColor:"var(--c-n)",copy:n("ni.fieldNotes.mirror")},vignettes:[n("ni.fieldNotes.vignette.meeting"),n("ni.fieldNotes.vignette.loop"),n("ni.fieldNotes.vignette.grip"),n("ni.fieldNotes.vignette.mechanicsHunch"),n("ni.fieldNotes.vignette.cantJustKnow"),n("ni.fieldNotes.vignette.mistakenForSi"),n("ni.fieldNotes.vignette.brainstorm")]};return{COL:i,SLOTS:p,CHARACTER:g,FEEDERS:f,SERIES:s,GRIP_T:w,COSTS:b,RECOVERY:v,LAB:k,ZONE_F:T}}export{j as l};
